import math

def cosine_similarity(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        raise ValueError("zero vector")
    return dot / (na * nb)

def top_k(query, docs, k):
    scored = [(doc_id, cosine_similarity(query, vec)) for doc_id, vec in docs.items()]
    scored.sort(key=lambda pair: (-pair[1], pair[0]))
    return scored[:k]


docs = {"reset": [0.9, 0.1, 0.0], "parcel": [0.0, 0.2, 0.95], "billing": [0.1, 0.95, 0.1]}
print(top_k([0.8, 0.0, 0.1], docs, 2))
